public class Q23_Thread_Lifecycle { public static void main(String[] args) throws InterruptedException { Thread t=new Thread(()->{try{Thread.sleep(300);}catch(InterruptedException e){Thread.currentThread().interrupt();}}); System.out.println("Before start: "+t.getState()); t.start(); System.out.println("After start (may be RUNNABLE): "+t.getState()); Thread.sleep(50); System.out.println("During sleep: "+t.getState()); t.join(); System.out.println("After finish: "+t.getState()+" (TERMINATED)"); /* RUNNING is represented as RUNNABLE by Java's Thread.State API. */ } }
